def _rules_hash(rules):
    """Same canonical hash as fantaball.scoring.rules_hash (kept inline so this migration never changes)."""
    import hashlib
    import json
    canon = json.dumps({k: round(float(v), 4) for k, v in sorted(rules.items())}, sort_keys=True)
    return hashlib.sha256(canon.encode()).hexdigest()[:32]


def _migrate_existing_data():
    """Existing databases only contain the SIMULATED demo world: relabel it and give every league a rule set."""
    import json
    conn = op.get_bind()
    conn.execute(sa.text("UPDATE sports SET code = 'nba_demo', name = 'NBA Basketball (simulated demo)', data_source = 'demo' WHERE code = 'nba'"))
    conn.execute(sa.text("UPDATE sports SET data_source = 'demo' WHERE code = 'nhl'"))
    rows = conn.execute(sa.text(
        "SELECT sc.id, sc.rules, l.sport_id FROM scoring_configs sc JOIN leagues l ON l.id = sc.league_id")).fetchall()
    for cfg_id, rules, sport_id in rows:
        rules = json.loads(rules) if isinstance(rules, str) else rules
        h = _rules_hash(rules)
        rs = conn.execute(sa.text("SELECT id FROM scoring_rulesets WHERE sport_id = :s AND rules_hash = :h"), {"s": sport_id, "h": h}).scalar()
        if rs is None:
            conn.execute(sa.text("INSERT INTO scoring_rulesets (sport_id, rules_hash, rules, is_template, created_at) VALUES (:s, :h, :r, 0, CURRENT_TIMESTAMP)"),
                         {"s": sport_id, "h": h, "r": json.dumps(rules)})
            rs = conn.execute(sa.text("SELECT id FROM scoring_rulesets WHERE sport_id = :s AND rules_hash = :h"), {"s": sport_id, "h": h}).scalar()
        conn.execute(sa.text("UPDATE scoring_configs SET ruleset_id = :r WHERE id = :i"), {"r": rs, "i": cfg_id})


